fn main() {
    let original: Vec<String> = vec![
        "one".to_string(),
        "two".to_string(),
        "three".to_string(),
        "four".to_string(),
        "five".to_string(),
    ];

    // Clone the vector to create a new independent vector
    let cloned = original.clone();

    // Drop the cloned vector explicitly to ensure it's deallocated
    drop(cloned);

    // Verify that the original vector is still valid and can be used
    assert_eq!(original.len(), 5);
    assert_eq!(original[0], "one");

    // Drop the original vector to ensure it's deallocated
    drop(original);

    // If we reach here, the program completed successfully
    println!("Ownership test passed");
}
